static unsigned int add_one_chunk ( png_bytep list , unsigned int count , png_const_bytep add , int keep ) { int i ; for ( i = 0 ; i < count ; ++ i , list += 5 ) { if ( memcmp ( list , add , 4 ) == 0 ) { list [ 4 ] = ( png_byte ) keep ; return count ; } } if ( keep != PNG_HANDLE_CHUNK_AS_DEFAULT ) { ++ count ; memcpy ( list , add , 4 ) ; list [ 4 ] = ( png_byte ) keep ; } return count ; } 